import 'dart:js_interop';
import 'package:web/web.dart' as web;

web.AudioContext? _sharedAudioCtx;
bool _unlockInitialized = false;

web.AudioContext _getContext() {
  _sharedAudioCtx ??= web.AudioContext();
  if (_sharedAudioCtx!.state == 'suspended') {
    try {
      _sharedAudioCtx!.resume();
    } catch (_) {}
  }
  return _sharedAudioCtx!;
}

void _initUnlock() {
  if (_unlockInitialized) return;
  _unlockInitialized = true;
  try {
    final unlock = ((web.Event _) {
      try {
        if (_sharedAudioCtx != null && _sharedAudioCtx!.state == 'suspended') {
          _sharedAudioCtx!.resume();
        }
      } catch (_) {}
    }).toJS;
    web.window.addEventListener('pointerdown', unlock);
    web.window.addEventListener('keydown', unlock);
    web.window.addEventListener('click', unlock);
    web.window.addEventListener('touchstart', unlock);
  } catch (_) {}
}

const String _buzzerB64 = '';

void playWebChime() {
  _initUnlock();

  // 1. Play HTMLAudioElement with embedded WAV data
  try {
    final audio = web.document.createElement('audio') as web.HTMLAudioElement;
    audio.src = 'data:audio/wav;base64,' + _buzzerB64;
    audio.volume = 1.0;
    audio.play();
  } catch (_) {}

  // 2. Play WebAudio synthesizer oscillator
  try {
    final ctx = _getContext();
    final now = ctx.currentTime;
    final osc = ctx.createOscillator();
    final gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.connect(gain);
    gain.connect(ctx.destination);

    // Urgent dual-pulse emergency buzzer: 920Hz -> 1250Hz -> 920Hz -> 1250Hz
    osc.frequency.setValueAtTime(920, now);
    osc.frequency.setValueAtTime(1250, now + 0.12);
    osc.frequency.setValueAtTime(920, now + 0.24);
    osc.frequency.setValueAtTime(1250, now + 0.36);

    gain.gain.setValueAtTime(0.85, now);
    gain.gain.setValueAtTime(0.85, now + 0.48);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.55);

    osc.start(now);
    osc.stop(now + 0.55);
  } catch (_) {}
}
